cd /root/t9
kubectl get sts web -o jsonpath='{.spec.updateStrategy}{"\n"}'
echo "== scale 3->1 (order)"; kubectl scale sts web --replicas=1; for i in $(seq 1 12); do echo "$(date +%T) $(kubectl get pod -l app=web --no-headers | awk '{print $1":"$3}' | tr '\n' ' ')"; sleep 2; done; kubectl get pvc --no-headers | awk '{print $1, $2}'
echo "== scale 1->3"; kubectl scale sts web --replicas=3; kubectl rollout status sts/web >/dev/null; kubectl exec web-2 -- cat /usr/share/nginx/html/index.html
echo "== partition=2 canary"; kubectl patch sts web -p '{"spec":{"updateStrategy":{"type":"RollingUpdate","rollingUpdate":{"partition":2}}}}'; kubectl set image sts/web nginx=nginx:1.28-alpine; sleep 20; kubectl get pod -l app=web -o custom-columns=NAME:.metadata.name,IMAGE:.spec.containers[0].image,REV:.metadata.labels.controller-revision-hash; kubectl get sts web -o jsonpath='{.status.currentRevision} {.status.updateRevision} updated={.status.updatedReplicas}{"\n"}'
echo "== partition=0"; kubectl patch sts web -p '{"spec":{"updateStrategy":{"rollingUpdate":{"partition":0}}}}'; for i in $(seq 1 20); do echo "$(date +%T) $(kubectl get pod -l app=web --no-headers -o custom-columns=N:.metadata.name,I:.spec.containers[0].image,R:.status.containerStatuses[0].ready | tr -s ' ' | tr '\n' ' ')"; sleep 2; done; kubectl rollout status sts/web; kubectl rollout history sts/web
echo "== OnDelete"; kubectl patch sts web --type merge -p '{"spec":{"updateStrategy":{"type":"OnDelete","rollingUpdate":null}}}'; kubectl set image sts/web nginx=nginx:1.27-alpine; sleep 10; kubectl get pod -l app=web -o custom-columns=NAME:.metadata.name,IMAGE:.spec.containers[0].image; kubectl delete pod web-1; kubectl wait --for=condition=Ready pod/web-1 --timeout=60s; kubectl get pod -l app=web -o custom-columns=NAME:.metadata.name,IMAGE:.spec.containers[0].image; kubectl exec web-1 -- cat /usr/share/nginx/html/index.html
echo "== delete sts (cascade) & reapply"; kubectl delete sts web; sleep 10; kubectl get pod,pvc --no-headers; kubectl apply -f sts.yaml; kubectl rollout status sts/web; for i in 0 1 2; do kubectl exec web-$i -- cat /usr/share/nginx/html/index.html; done
